import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState } from 'react';

export default function Header() {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { href: '/', label: 'Home' },
    { href: '/shop', label: 'Shop' },
    { href: '/about', label: 'About' },
  ];

  return (
    <header className="sticky top-0 z-50 bg-background/95 backdrop-blur-sm border-b border-border">
      <div className="container mx-auto px-6">
        <div className="flex h-20 items-center justify-between">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0" aria-label="Artisan Goods Co. home">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Artisan Goods Co."
              className="h-10 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-8">
            {navItems.map((item) => (
              <Link
                key={item.href}
                to={item.href}
                className={`relative text-sm font-medium tracking-wide transition-colors group ${
                  location.pathname === item.href
                    ? 'text-primary'
                    : 'text-foreground hover:text-primary'
                }`}
              >
                {item.label}
                <span
                  className={`absolute -bottom-1 left-0 h-px bg-primary transition-all duration-300 ${
                    location.pathname === item.href ? 'w-full' : 'w-0 group-hover:w-full'
                  }`}
                />
              </Link>
            ))}
            <Link
              to="/shop"
              className="ml-2 px-5 py-2 bg-primary text-primary-foreground text-sm font-medium rounded-full hover:bg-primary/90 transition-colors"
            >
              Shop Now
            </Link>
          </nav>

          {/* Mobile hamburger */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 hover:bg-muted rounded-md transition-colors"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>

        {/* Mobile menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border py-5">
            <nav className="flex flex-col gap-1">
              {navItems.map((item) => (
                <Link
                  key={item.href}
                  to={item.href}
                  className={`text-sm font-medium py-3 px-2 rounded-md transition-colors ${
                    location.pathname === item.href
                      ? 'text-primary bg-muted'
                      : 'text-foreground hover:text-primary hover:bg-muted'
                  }`}
                  onClick={() => setIsMobileMenuOpen(false)}
                >
                  {item.label}
                </Link>
              ))}
              <Link
                to="/shop"
                className="mt-3 px-5 py-3 bg-primary text-primary-foreground text-sm font-medium rounded-full text-center hover:bg-primary/90 transition-colors"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                Shop Now
              </Link>
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

import { Link, useLoaderData } from 'react-router-dom';
import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { useState } from 'react';
import type { Product } from '@/server/api/products/GET';

export async function loader() {
  const res = await fetch('/api/products/featured');
  if (!res.ok) throw new Response(null, { status: res.status });
  const featured: Product[] = await res.json();
  return { featured };
}

const categoryLabels: Record<string, string> = {
  pottery: 'Pottery',
  textiles: 'Textiles',
  woodwork: 'Woodwork',
  jewelry: 'Jewelry',
};

export default function HomePage() {
  const { featured } = useLoaderData() as { featured: Product[] };
  const [email, setEmail] = useState('');
  const [subscribed, setSubscribed] = useState(false);

  function handleSubscribe(e: React.FormEvent) {
    e.preventDefault();
    if (email) setSubscribed(true);
  }

  return (
    <>
      <Helmet>
        <title>Artisan Goods Co. — Handcrafted with Care</title>
        <meta
          name="description"
          content="Shop handmade pottery, textiles, woodwork, and jewelry crafted by independent artisans. Every piece tells a story."
        />
      </Helmet>

      {/* ── Hero ── */}
      <section className="relative h-[90vh] min-h-[560px] flex items-end overflow-hidden">
        <img
          src="/airo-assets/images/pages/home/hero"
          alt="Artisan workshop with warm natural light"
          className="absolute inset-0 w-full h-full object-cover"
          fetchPriority="high"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-gray-900/80 via-gray-900/30 to-transparent" />

        <div className="relative z-10 container mx-auto px-6 pb-20 md:pb-28">
          <motion.div
            initial={{ opacity: 0, y: 28 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7, ease: 'easeOut' }}
            className="max-w-2xl"
          >
            <p className="text-sm font-medium tracking-widest uppercase text-primary mb-4">
              Made by hand, made with heart
            </p>
            <h1 className="font-heading text-5xl md:text-7xl font-bold text-white leading-tight mb-6">
              Handcrafted<br />with Care
            </h1>
            <p className="text-lg text-white/80 mb-10 max-w-lg leading-relaxed">
              Discover one-of-a-kind goods made by independent artisans — pottery, textiles, woodwork, and jewelry that bring warmth to everyday life.
            </p>
            <div className="flex flex-wrap gap-4">
              <Link
                to="/shop"
                className="px-8 py-4 bg-primary text-primary-foreground font-medium rounded-full hover:bg-primary/90 transition-all hover:shadow-lg hover:shadow-primary/30"
              >
                Shop Now
              </Link>
              <Link
                to="/about"
                className="px-8 py-4 border border-white/50 text-white font-medium rounded-full hover:bg-white/10 transition-colors"
              >
                Our Story
              </Link>
            </div>
          </motion.div>
        </div>
