                      alt={product.name}
                      className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-gray-900/40 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                  </div>
                  <div className="mt-4 flex items-start justify-between gap-4">
                    <div>
                      <span className="text-xs font-semibold tracking-wider uppercase text-primary">
                        {categoryLabels[product.category]}
                      </span>
                      <h3 className="font-heading text-xl font-semibold text-foreground mt-1 group-hover:text-primary transition-colors">
                        {product.name}
                      </h3>
                    </div>
                    <span className="text-lg font-semibold text-foreground shrink-0">
                      ${product.price}
