        </div>
      </section>

      {/* ── Craft Values Strip ── */}
      <section className="py-16 bg-muted border-y border-border">
        <div className="container mx-auto px-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-10 text-center">
            {[
              { title: 'Made by Hand', body: 'Every item is crafted individually by skilled artisans — no mass production, ever.' },
              { title: 'Natural Materials', body: 'We source clay, wood, fiber, and metal responsibly from local and sustainable suppliers.' },
              { title: 'One of a Kind', body: 'Natural variation means your piece is truly unique. Imperfection is the mark of authenticity.' },
            ].map((v, i) => (
              <motion.div
                key={v.title}
                initial={{ opacity: 0, y: 16 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.4, delay: i * 0.1 }}
                className="flex flex-col items-center gap-3"
              >
                <h3 className="font-heading text-xl font-semibold text-foreground">{v.title}</h3>
                <p className="text-sm text-muted-foreground leading-relaxed max-w-xs">{v.body}</p>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* ── Newsletter — Asymmetric Layout ── */}
      <section className="py-24 container mx-auto px-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-12 items-center">
          {/* Decorative left side */}
          <div className="relative">
            {/* Organic shape accent */}
            <div className="absolute -top-8 -left-8 w-48 h-48 rounded-full bg-primary/10 blur-3xl pointer-events-none" />
            <div className="absolute -bottom-8 -right-8 w-32 h-32 rounded-full bg-primary/15 blur-2xl pointer-events-none" />
            <div className="relative bg-muted rounded-3xl p-10 border border-border">
              <p className="text-xs font-semibold tracking-widest uppercase text-primary mb-4">
                Stay in the loop
              </p>
              <h2 className="font-heading text-4xl md:text-5xl font-bold text-foreground leading-tight mb-4">
                Letters from<br />the Workshop
              </h2>
              <p className="text-muted-foreground leading-relaxed">
                New arrivals, behind-the-scenes stories, and seasonal collections — delivered to your inbox a few times a month.
              </p>
            </div>
          </div>

          {/* Form right side */}
          <div className="flex flex-col gap-6">
            {subscribed ? (
              <motion.div
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                className="text-center py-12"
              >
                <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center mx-auto mb-4">
                  <span className="text-2xl">✦</span>
                </div>
                <h3 className="font-heading text-2xl font-semibold text-foreground mb-2">You're in!</h3>
                <p className="text-muted-foreground">Welcome to the Artisan Goods community. Watch your inbox for our next letter.</p>
