                </p>
                <form onSubmit={handleSubscribe} className="flex flex-col gap-4">
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="your@email.com"
                    required
                    className="w-full px-5 py-4 rounded-full border border-border bg-background text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/40 transition"
                  />
                  <button
                    type="submit"
                    className="w-full px-8 py-4 bg-primary text-primary-foreground font-medium rounded-full transition-all hover:bg-primary/90 hover:shadow-lg hover:shadow-primary/20 active:scale-[0.98]"
                  >
                    Subscribe — it's free
                  </button>
                </form>
                <p className="text-xs text-muted-foreground text-center">
                  No spam, ever. Unsubscribe anytime.
                </p>
              </>
            )}
          </div>
        </div>
      </section>
    </>
  );
}

import { useLoaderData } from 'react-router-dom';
import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { useState } from 'react';
import type { Product } from '@/server/api/products/GET';

export async function loader() {
  const res = await fetch('/api/products');
  if (!res.ok) throw new Response(null, { status: res.status });
  const products: Product[] = await res.json();
  return { products };
}

type Category = 'all' | 'pottery' | 'textiles' | 'woodwork' | 'jewelry';

const filters: { value: Category; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'pottery', label: 'Pottery' },
  { value: 'textiles', label: 'Textiles' },
  { value: 'woodwork', label: 'Woodwork' },
  { value: 'jewelry', label: 'Jewelry' },
];

export default function ShopPage() {
  const { products } = useLoaderData() as { products: Product[] };
  const [activeCategory, setActiveCategory] = useState<Category>('all');

  const filtered =
    activeCategory === 'all'
      ? products
      : products.filter((p) => p.category === activeCategory);

  return (
    <>
      <Helmet>
        <title>Shop — Artisan Goods Co.</title>
        <meta
          name="description"
          content="Browse handmade pottery, textiles, woodwork, and jewelry from independent artisans. Every piece is one of a kind."
        />
      </Helmet>

      {/* Page header */}
      <div className="bg-muted border-b border-border">
        <div className="container mx-auto px-6 py-16">
          <p className="text-xs font-semibold tracking-widest uppercase text-primary mb-3">
            Handmade goods
          </p>
          <h1 className="font-heading text-5xl md:text-6xl font-bold text-foreground">
            The Shop
          </h1>
          <p className="mt-4 text-muted-foreground max-w-md leading-relaxed">
            Every item is made by hand, in small batches, by artisans who care deeply about their craft.
          </p>
        </div>
      </div>

      <div className="container mx-auto px-6 py-12">
        {/* Category filters */}
        <div className="flex flex-wrap gap-3 mb-12">
          {filters.map((f) => (
            <button
              key={f.value}
              onClick={() => setActiveCategory(f.value)}
              className={`px-5 py-2 rounded-full text-sm font-medium transition-all ${
                activeCategory === f.value
                  ? 'bg-primary text-primary-foreground shadow-sm'
                  : 'bg-muted text-foreground border border-border hover:border-primary/40 hover:text-primary'
              }`}
            >
              {f.label}
              {activeCategory === f.value && (
                <span className="ml-2 text-xs opacity-75">
                  ({filtered.length})
                </span>
              )}
            </button>
          ))}
        </div>

        {/* Product grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
          {filtered.map((product, i) => (
            <motion.article
              key={product.id}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.4, delay: (i % 3) * 0.08, ease: 'easeOut' }}
              className="group cursor-pointer"
            >
              {/* Image */}
              <div className="relative aspect-square overflow-hidden rounded-2xl bg-muted mb-4">
                <img
                  src={product.imageUrl}
                  alt={product.name}
                  className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                />
                {/* Category badge */}
                <span className="absolute top-3 left-3 px-3 py-1 bg-background/90 backdrop-blur-sm text-xs font-semibold tracking-wide uppercase text-primary rounded-full">
                  {product.category}
                </span>
              </div>

              {/* Info */}
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1 min-w-0">
                  <h2 className="font-heading text-lg font-semibold text-foreground group-hover:text-primary transition-colors truncate">
                    {product.name}
                  </h2>
                  <p className="text-sm text-muted-foreground mt-1 line-clamp-2 leading-relaxed">
                    {product.description}
                  </p>
                </div>
                <span className="text-lg font-semibold text-foreground shrink-0">
                  ${product.price}
                </span>
              </div>

              {/* Add to cart placeholder */}
              <button className="mt-4 w-full py-3 border border-border rounded-full text-sm font-medium text-foreground hover:bg-primary hover:text-primary-foreground hover:border-primary transition-all duration-200">
                Add to Cart
              </button>
            </motion.article>
          ))}
        </div>

        {filtered.length === 0 && (
          <div className="text-center py-24 text-muted-foreground">
            <p className="font-heading text-2xl mb-2">Nothing here yet</p>
            <p className="text-sm">Check back soon — our artisans are always creating.</p>
          </div>
        )}
      </div>
    </>
  );
}

